import{_ as a,a as t,c as l,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 31 The sculptor speaks","description":"学习 独立主格的主语与分词，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 31 The sculptor speaks","description":"学习 独立主格的主语与分词，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 独立主格的主语与分词，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 30 Exploring the sea-floor","link":"/life/english/new-concept/book-4/unit-04/lesson-030"},"next":{"text":"第四册：流利英语 · Lesson 32 Galileo reborn","link":"/life/english/new-concept/book-4/unit-04/lesson-032"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 30 Exploring the sea-floor","link":"/life/english/new-concept/book-4/unit-04/lesson-030"},"next":{"text":"第四册：流利英语 · Lesson 32 Galileo reborn","link":"/life/english/new-concept/book-4/unit-04/lesson-032"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-04/lesson-031.md","filePath":"life/english/new-concept/book-4/unit-04/lesson-031.md"}'),n={name:"life/english/new-concept/book-4/unit-04/lesson-031.md"};function s(r,e,i,h,c,d){return t(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-31-the-sculptor-speaks" tabindex="-1">第四册：流利英语 · Lesson 31 The sculptor speaks <a class="header-anchor" href="#第四册-流利英语-·-lesson-31-the-sculptor-speaks" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 31 The sculptor speaks&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元 4</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>通过雕塑家的自述训练艺术论述阅读，关注作者如何从材料、触感和空间说明创作选择。区分艺术家的意图与观众实际体验，避免把一种艺术观当作唯一标准。重点使用独立主格结构交代背景，并判断什么时候保留完整从句更容易理解。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>sculpture</td><td>/ˈskʌlptʃə/</td><td>n.</td><td>雕塑</td><td>a bronze sculpture</td></tr><tr><td>clay</td><td>/kleɪ/</td><td>n.</td><td>黏土</td><td>wet clay</td></tr><tr><td>volume</td><td>/ˈvɒljuːm/</td><td>n.</td><td>体积；立体感</td><td>a sense of volume</td></tr><tr><td>form</td><td>/fɔːm/</td><td>n.</td><td>形态</td><td>an abstract form</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>work with — 使用某材料创作</li><li>give shape to — 赋予具体形态</li></ul><h2 id="语法讲解-独立主格的主语与分词" tabindex="-1">语法讲解：独立主格的主语与分词 <a class="header-anchor" href="#语法讲解-独立主格的主语与分词" aria-label="Permalink to &quot;语法讲解：独立主格的主语与分词&quot;">​</a></h2><p>独立主格结构有自己的名词或代词逻辑主语，如 The clay still wet, the artist covered the model。它可补充时间、原因或伴随背景，不必与主句主语一致。名词后可接分词、形容词或介词短语。与普通分词状语不同，Materials prepared, we began 中 prepared 的承受者是 materials。正式写作中应避免连续堆叠；背景关系可能含糊时，用 because 或 after 完整从句更清楚。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>The clay still damp, the sculptor covered the model before leaving.</p></blockquote><p>黏土还湿着，雕塑家离开前盖住了模型。</p><p>The clay still damp 有自己的主语 clay 和形容词 damp，补充背景；主句主语是 sculptor。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>不要把独立主格误写成 The clay was still damp, the sculptor covered…；两个完整句不能仅用逗号连接。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>在 The clay still damp 后明确停顿，主句重新建立节奏；不要为方便朗读擅自加 was 而仍只用逗号连接。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The surface still rough, the artist examined the model from the side. She removed a small piece near the base. To me, the new shape seemed lighter and more balanced.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>写三句工作室观察：材料状态、创作者动作、你对形式的个人感受。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>独立主格提供材料背景，末句 To me 将观众感受与作者意图区分。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>示例背景结构的逻辑主语是什么？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> the clay</p><p><strong>解析：</strong> damp 描述 clay，而不是 sculptor。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>用 because 将示例改为明确原因从句。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> Because the clay was still damp, the sculptor covered the model before leaving.</p><p><strong>解析：</strong> 完整从句补入 was 并明确因果理解。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填空：The tools ___, we began work.（prepare 的过去分词）</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> prepared</p><p><strong>解析：</strong> 工具是被准备的，使用过去分词。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：独立主格的主语与分词。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-04/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-04/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-04/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-04/lesson-030">上一课</a> · <a href="/life/english/new-concept/book-4/unit-04/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-04/lesson-032">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=a(n,[["render",s]]);export{u as __pageData,b as default};
